content:
return NULL;
        }
        memset(mov, 0, sizeof(GF_ISOFile));

        /*init the boxes*/
        mov->TopBoxes = gf_list_new();
        if (!mov->TopBoxes) {
                gf_isom_set_last_error(NULL, GF_OUT_OF_MEM);
